    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tool implementations ---
var notebook = new ResearchNotebook();

[Description("Search the web for information on a query. Returns a list of relevant snippets.")]
static string SearchWeb(
    [Description("The search query to look up")] string query)
{
    // Simulated web search results keyed by topic keywords.
    var results = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            "Quantum computers use qubits that can exist in superposition, enabling parallel computation on an exponential scale compared to classical bits.",
            "Google's Willow chip (2024) achieved quantum error correction below the surface-code threshold, a key milestone toward fault-tolerant quantum computing.",
            "IBM's roadmap targets a 100,000-qubit system by 2033. Current machines (1,000+ qubits) are used for chemistry simulation and optimization.",
            "Post-quantum cryptography standards (ML-KEM, ML-DSA) were finalized by NIST in 2024 to guard against future quantum attacks on RSA/ECC."
        ],
        ["artificial intelligence"] =
        [
            "Large language models (LLMs) like GPT-4o use transformer architectures with hundreds of billions of parameters trained on internet-scale text corpora.",
            "AI agents combine LLMs with tool use and memory to perform multi-step tasks autonomously, from coding to scientific research.",
            "The EU AI Act (2024) classifies AI systems by risk level, banning social scoring and requiring transparency for high-risk applications.",
            "Multimodal models now process text, images, audio, and video in a single architecture, enabling richer reasoning across data types."
        ],
        ["climate change"] =
        [
            "Global average temperature has risen ~1.2 °C above pre-industrial levels; the Paris Agreement targets limiting warming to 1.5 °C.",
            "Renewable energy capacity surpassed 4,000 GW globally in 2024, with solar PV alone adding over 400 GW in a single year.",
            "Ocean acidification has increased 30 % since pre-industrial times, threatening coral reefs and marine food chains.",
            "Carbon capture and storage (CCS) projects are scaling up, but current capacity removes less than 0.1 % of annual global CO₂ emissions."
        ],
    };

    foreach (var (key, snippets) in results)
    {
        if (query.Contains(key, StringComparison.OrdinalIgnoreCase))
        {
            return string.Join("\n\n", snippets.Select((s, i) => $"[Result {i + 1}] {s}"));
        }
    }

    return $"[Result 1] No specific results found for '{query}'. Try a broader search term such as 'artificial intelligence', 'quantum computing', or 'climate change'.";
}

var searchTool = AIFunctionFactory.Create(SearchWeb);
var saveNoteTool = AIFunctionFactory.Create(notebook.SaveNote);
var readNotesTool = AIFunctionFactory.Create(notebook.ReadNotes);

// --- Build the agent ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. Your job is to thoroughly research a topic
        the user provides by searching the web, saving important findings as notes,
        and then producing a concise summary.

        Follow this workflow:
        1. Search the web for the topic using one or more queries.
        2. Save each key finding as a note using the SaveNote tool.
        3. Read back all your notes to verify completeness.
        4. Produce a final summary that synthesizes the findings, citing the
           notes you saved. Format the summary with clear sections.

        Always search before answering. Never fabricate information — only use
        facts returned by the search tool.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking",
    tools: [searchTool, saveNoteTool, readNotesTool]);

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic = args.Length > 0
    ? string.Join(' ', args)
    : "quantum computing";

Console.WriteLine($"📋 Research topic: {topic}");
Console.WriteLine(new string('─', 50));
Console.WriteLine();

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

Console.WriteLine(response.Text);
Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"📝 Notes collected: {notebook.Count}");

// --- Notebook helper ---
public sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    [Description("Save a research note with a title and content for later reference.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The note content to save")] string content)
    {
        _notes.Add((title, content));
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Read all saved research notes.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"Note #{i + 1} — {n.Title}\n{n.Content}"));
    }
}

